<script setup>
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue';
import { ElMessage } from 'element-plus';
import DocumentSkuV2 from './DocumentSkuV2.vue';
import DocumentProductImageV2 from './DocumentProductImageV2.vue';
import * as api from '../../api/supplyCostsV2';
import PurchaseContractV2 from './PurchaseContractV2.vue';
import PaymentLedgerV2 from './PaymentLedgerV2.vue';
import { natureLabel, validateAllocations } from '../../utils/payeeSettlement';
import * as voucherApi from '../../api/supplyChainV2';
import { fetchApiFile } from '../../api/request';
import { useAuthStore } from '../../stores/auth';
const props=defineProps({kind:{type:String,required:true},id:{type:[String,Number],required:true},version:{type:[String,Number],default:0}}),emit=defineEmits(['updated']);
const auth=useAuthStore(),canWrite=computed(()=>!auth.authorizationStale&&auth.hasPermission('supply.v2.manage')),editable=computed(()=>canWrite.value&&context.value?.target?.fee_editable!==false),kindLabel=computed(()=>({shipment:'发货单',batch:'发运批次',inbound:'入库单'})[props.kind]||props.kind),settlementLabel=computed(()=>({unsettled:'未结算',partially_settled:'部分结算',settled:'已结算'})[context.value?.settlement?.status]||'未登记');
const domesticPaymentsOpen=ref(false);
const loading=ref(false),busy=ref(false),error=ref(''),context=ref(null),fee=reactive({amount:'',state:'estimated',method:'volume',volume_percent:'50',billed_cbm:'',notes:'',reason:''}),measurements=ref([]),feeItems=ref([]),breakdown=ref([]),settlement=reactive({recorded_amount:'',reference_number:'',date:'',notes:'',reason:'',payee_allocations:[]}),keys=new Map(),voucherUploadKeys=new Map(),savedSnapshot=ref(''),refreshPending=ref(false),selectedVersion=ref(null),uploadingVoucherIds=ref(new Set());
function snapshot(){return JSON.stringify({fee:{amount:fee.amount,state:fee.state,method:fee.method,volume_percent:fee.volume_percent,billed_cbm:fee.billed_cbm,notes:fee.notes,reason:fee.reason,item_breakdown:breakdown.value},measurements:measurements.value.map(m=>({shipment_line_id:m.shipment_line_id,volume_cbm:m.volume_cbm,weight_kg:m.weight_kg})),settlement:{recorded_amount:settlement.recorded_amount,reference_number:settlement.reference_number.trim(),date:settlement.date,notes:settlement.notes,reason:settlement.reason,payee_allocations:settlement.payee_allocations}});}
watch(breakdown, rows=>{if(['batch','inbound'].includes(props.kind)&&rows.length)fee.amount=rows.reduce((n,row)=>n+Number(row.amount||0),0).toFixed(4);},{deep:true});
const fieldErrors=ref({});
const dirty=computed(()=>!!savedSnapshot.value&&snapshot()!==savedSnapshot.value);
function unwrap(r){if(!r?.success){const e=new Error(r?.message||'请求失败');e.details=r?.data;throw e;}return r.data;}
const fieldLabels={amount:'费用金额',volume_percent:'体积分摊比例',billed_cbm:'计费体积',reason:'原因',recorded_amount:'累计已结算金额',reference_number:'参考单号',date:'日期',volume_cbm:'本行总体积',weight_kg:'本行总重量',notes:'备注'};
function showError(e,scope){
  const details=e.details||e.response?.data?.data;
  const messages=[];
  function visit(value,path=[]){
    if(Array.isArray(value)&&value.every(v=>typeof v==='string')){visit(value.join('；'),path);return;}
    if(value&&typeof value==='object'){Object.entries(value).forEach(([k,v])=>visit(v,[...path,k]));return;}
    if(value==null)return;
    let key=path.join('.'),label=fieldLabels[path.at(-1)]||path.at(-1)||'';
    if(path[0]==='measurements'){
      const row=measurements.value[Number(path[1])];
      key=`measurements.${row?.shipment_line_id}.${path[2]}`;
      label=`第 ${Number(path[1])+1} 行 ${row?.sku||''} ${label}`;
    }else if(fieldLabels[path[0]])key=`${scope}.${path[0]}`;
    else label='';
    if(key)fieldErrors.value[key]=String(value);
    messages.push(`${label?label+'：':''}${value}`);
  }
  if(details)visit(details);
  error.value=messages.length?messages.join('；'):e.message||'保存失败，请重试。';
}
function validateForm(scope){
  fieldErrors.value={};const messages=[];
  const fail=(key,label,message)=>{fieldErrors.value[key]=message;messages.push(`${label}：${message}`);};
  const number=(key,value,precision,label,required,integerDigits)=>{
    const raw=String(value??'').trim();
    if(!raw){if(required)fail(key,label,'请填写');return null;}
    try{const parsed=decimal(raw,precision,label,true);if(parsed.split('.')[0].replace(/^0+/,'').length>integerDigits)throw new Error(`整数部分最多 ${integerDigits} 位`);return Number(parsed);}
    catch(e){fail(key,label,e.message);return null;}
  };
  const required=(key,value,label,max)=>{if(!String(value??'').trim())fail(key,label,'请填写');else if(String(value).length>max)fail(key,label,`最多 ${max} 个字符`);};
  if(scope==='fee'){
    const amount=number('fee.amount',fee.amount,4,'费用金额',!(['batch','inbound'].includes(props.kind)&&breakdown.value.length),16);
    required('fee.reason',fee.reason,'费用维护原因',10000);
    const percent=fee.method==='mixed'?number('fee.volume_percent',fee.volume_percent,2,'体积分摊比例',true,3):fee.method==='volume'?100:0;
    if(percent>100)fail('fee.volume_percent','体积分摊比例','不能超过 100%');
    if(props.kind!=='shipment')number('fee.billed_cbm',fee.billed_cbm,6,'计费体积',false,10);
    measurements.value.forEach((row,index)=>{
      for(const [name,label,needed] of [['volume_cbm','总体积',percent>0],['weight_kg','总重量',percent<100]]){
        const key=`measurements.${row.shipment_line_id}.${name}`,caption=`第 ${index+1} 行 ${row.sku} ${label}`;
        const value=number(key,row[name],6,caption,false,14);
        if(amount>0&&Number(row.quantity)>0&&needed&&!(value>0)&&!fieldErrors.value[key])fail(key,caption,'当前分摊方式需要大于 0 的本行总量');
      }
    });
  }else{
    number('settlement.recorded_amount',settlement.recorded_amount,4,'累计已结算金额',true,20);
    required('settlement.reference_number',settlement.reference_number,'参考单号',200);
    required('settlement.reason',settlement.reason,'结算登记原因',10000);
    const date=String(settlement.date||'');
    if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||Number.isNaN(Date.parse(date))||new Date(date).toISOString().slice(0,10)!==date)fail('settlement.date','日期','请选择有效日期');
  }
  if(messages.length){error.value=messages.join('；');return false;}return true;
}
function idempotent(slot,body,run){const f=JSON.stringify(body);let p=keys.get(slot);if(!p||p.f!==f){p={f,key:api.createIdempotencyKey()};keys.set(slot,p);}return run(p.key).then(r=>{const d=unwrap(r);keys.delete(slot);return d;});}
function hydrate(data){context.value=data;feeItems.value=data.fee_item_options||[];const f=data.fee||{};breakdown.value=(f.item_breakdown||[]).map(row=>({...row,amount:String(row.amount)}));for(const row of breakdown.value){if(!feeItems.value.some(item=>String(item.id)===String(row.fee_item_id)))feeItems.value.push({id:row.fee_item_id,name:row.name,default_nature:row.nature,is_active:false});}Object.assign(fee,{amount:f.amount==null?'':String(f.amount),state:f.state||'estimated',method:f.method||'volume',volume_percent:f.volume_percent==null?'50':String(f.volume_percent),billed_cbm:f.billed_cbm==null?'':String(f.billed_cbm),notes:f.notes||'',reason:''});measurements.value=(data.measurements||[]).map(m=>({...m,volume_cbm:m.volume_cbm==null?'':String(m.volume_cbm),weight_kg:m.weight_kg==null?'':String(m.weight_kg)}));const s=data.settlement||{};Object.assign(settlement,{recorded_amount:s.recorded_amount==null?'':String(s.recorded_amount),reference_number:s.reference_number||'',date:s.date||'',notes:s.notes||'',reason:'',payee_allocations:(s.allocations||[]).map(row=>({...row,amount:String(row.amount)}))});refreshPending.value=false;selectedVersion.value=null;savedSnapshot.value=snapshot();emit('updated',data.target);}
let contextGeneration=0;
async function load(){const token=++contextGeneration,kind=props.kind,id=props.id;loading.value=true;error.value='';fieldErrors.value={};try{const data=unwrap(await api.fetchCostContext(kind,id));if(token===contextGeneration&&kind===props.kind&&id===props.id)hydrate(data);}catch(e){if(token===contextGeneration)error.value=e.message||'费用信息读取失败';}finally{if(token===contextGeneration)loading.value=false;}}
onUnmounted(()=>{contextGeneration++;});
function decimal(v,precision,label,required=false){const s=String(v??'').trim();if(!s&&!required)return null;if(!new RegExp(`^\\d+(?:\\.\\d{1,${precision}})?$`).test(s))throw new Error(`${label}需为非负数且最多 ${precision} 位小数。`);return s;}
function feeTaxPreview(row){if(row.nature==='personal')return '对私：不拆税';if(row.tax_rate==null||row.tax_rate==='')return '税点未维护';const amount=Number(row.amount),rate=Number(row.tax_rate);if(!Number.isFinite(amount)||!Number.isFinite(rate)||rate<0||rate>100)return '请检查金额和税点';const tax=Math.round((amount-amount/(1+rate/100))*100)/100;return `含税 ${amount.toFixed(4)} · 税费约 ${tax.toFixed(2)} · 未税约 ${(amount-tax).toFixed(4)}（以保存结果为准）`;}
function addFeeItem(){breakdown.value.push({fee_item_id:'',amount:'0.0000',nature:'corporate'});}
function selectFeeItem(row){const item=feeItems.value.find(x=>String(x.id)===String(row.fee_item_id));if(item){row.nature=item.default_nature||'corporate';row.tax_rate=item.default_tax_rate??null;}}
function removeFeeItem(index){breakdown.value.splice(index,1);}
function methodLabel(value){return ({volume:'按体积',weight:'按重量',mixed:'体积与重量混合'})[value]||'—';}
function stageLabel(value){return ({shipped:'发货阶段',received:'入库阶段'})[value]||'—';}
function displayTime(value){if(!value)return '—';const date=new Date(value);return Number.isNaN(date.getTime())?'—':date.toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});}
function costLabel(state){return ({estimated:'暂估',confirmed:'已确认',recalculation_required:'待重算'})[state]||'尚未计算';}
function measurementPayload(){return measurements.value.map(row=>{const original=context.value.measurements.find(m=>m.shipment_line_id===row.shipment_line_id)||{};const value=(name,source,label)=>{const parsed=decimal(row[name],6,label);return row[source]==='manual_total'||String(row[name]??'')!==String(original[name]??'')?parsed:null;};return {shipment_line_id:row.shipment_line_id,volume_cbm:value('volume_cbm','volume_source','本行总体积'),weight_kg:value('weight_kg','weight_source','本行总重量')};});}
async function saveFee(){if(!editable.value||busy.value)return;error.value='';try{if(['batch','inbound'].includes(props.kind)&&breakdown.value.length)fee.amount=breakdown.value.reduce((n,row)=>n+Number(row.amount||0),0).toFixed(4);if(!validateForm('fee'))return;const body={expected_source_version:Number(context.value.target.version),expected_version:Number(context.value.fee?.version||0),amount:decimal(fee.amount,4,'费用金额',true),state:fee.state,method:fee.method,volume_percent:fee.method==='mixed'?decimal(fee.volume_percent,2,'体积分摊比例',true):null,billed_cbm:props.kind==='shipment'?null:decimal(fee.billed_cbm,6,'计费体积'),notes:fee.notes,reason:fee.reason.trim(),measurements:measurementPayload(),...(['batch','inbound'].includes(props.kind)?{item_breakdown:breakdown.value.map(x=>({fee_item_id:Number(x.fee_item_id),amount:decimal(x.amount,4,'分项金额',true),nature:x.nature,...('tax_rate' in x?{tax_rate:x.nature==='personal'?'0':x.tax_rate}:{} )}))}:{})};if(['batch','inbound'].includes(props.kind)&&body.item_breakdown.length){const sum=body.item_breakdown.reduce((n,x)=>n+Number(x.amount),0);body.amount=sum.toFixed(4);}if(fee.method==='mixed'&&Number(body.volume_percent)>100)throw new Error('体积分摊比例不能超过 100%。');busy.value=true;await idempotent('fee',body,k=>api.saveFee(props.kind,props.id,body,k));await load();ElMessage.success('费用已保存。');}catch(e){showError(e,'fee');}finally{busy.value=false;}}
async function calculate(){if(!canWrite.value||busy.value)return;const body={expected_source_version:Number(context.value.target.calculation_version),expected_input_fingerprint:context.value.input_fingerprint};busy.value=true;try{await idempotent('calculate',body,k=>api.calculateCost(context.value.target.calculation_kind,context.value.target.calculation_id,body,k));await load();ElMessage.success('成本已更新。');}catch(e){showError(e,'calculate');}finally{busy.value=false;}}
async function refreshAfterContractUpdate(){await load();}
async function recordSettlement(){if(!canWrite.value||!context.value?.settlement_supported||busy.value)return;error.value='';try{if(!validateForm('settlement'))return;const body={expected_source_version:Number(context.value.target.version),expected_version:Number(context.value.settlement?.version||0),recorded_amount:decimal(settlement.recorded_amount,4,'累计已结算金额',true),reference_number:settlement.reference_number.trim(),date:settlement.date,notes:settlement.notes,reason:settlement.reason.trim(),payee_allocations:validateAllocations(settlement.payee_allocations,settlement.recorded_amount)};busy.value=true;await idempotent('settlement',body,k=>api.recordSettlement(props.kind,props.id,body,k));await load();ElMessage.success('结算登记已保存。');}catch(e){showError(e,'settlement');}finally{busy.value=false;}}
async function uploadVoucher(row,event){const input=event?.target,file=input?.files?.[0];if(!file)return;if(!canWrite.value||!row?.id){ElMessage.error('请先保存结算登记后上传凭证。');input.value='';return;}if(file.size<=0||file.size>10*1024*1024||!(/\.(pdf|jpe?g|png)$/i.test(file.name))){ElMessage.error('请选择不超过10MB的 PDF、JPG 或 PNG 文件。');input.value='';return;}if((row.attachments||[]).length>=20){ElMessage.error('每条结算历史最多上传20个凭证。');input.value='';return;}const slot=`${row.id}:${file.name}:${file.size}:${file.lastModified}`;if(!voucherUploadKeys.has(slot))voucherUploadKeys.set(slot,voucherApi.createIdempotencyKey());uploadingVoucherIds.value=new Set([...uploadingVoucherIds.value,row.id]);try{const result=unwrap(await voucherApi.uploadSettlementVoucher(props.kind,props.id,row.id,file,voucherUploadKeys.get(slot)));voucherUploadKeys.delete(slot);row.attachments=[...(row.attachments||[]).filter(item=>item.id!==result.id),result];ElMessage.success('凭证已上传。');}catch(e){ElMessage.error(e.message||'凭证上传失败，可重试。');}finally{const next=new Set(uploadingVoucherIds.value);next.delete(row.id);uploadingVoucherIds.value=next;input.value='';}}
const voucherPreviewOpen=ref(false),voucherPreviewUrl=ref(''),voucherPreviewType=ref('');let previewGeneration=0;
function clearVoucherPreview(){previewGeneration++;if(voucherPreviewUrl.value)URL.revokeObjectURL(voucherPreviewUrl.value);voucherPreviewUrl.value='';voucherPreviewType.value='';}
async function previewVoucher(row,voucher){const token=++previewGeneration;try{const path=`/api/internal/supply-chain/v2/costs/${props.kind}/${props.id}/settlements/${row.id}/vouchers/${voucher.id}/download/`;const result=await fetchApiFile(path);if(token!==previewGeneration)return;if(!result?.success||!result.blob)throw new Error(result?.message||'凭证读取失败');if(!['application/pdf','image/png','image/jpeg'].includes(voucher.media_type))throw new Error('凭证格式不支持预览');if(voucherPreviewUrl.value)URL.revokeObjectURL(voucherPreviewUrl.value);voucherPreviewUrl.value=URL.createObjectURL(new Blob([result.blob],{type:voucher.media_type}));voucherPreviewType.value=voucher.media_type;voucherPreviewOpen.value=true;}catch(e){if(token===previewGeneration)ElMessage.error(e.message||'凭证读取失败');}}
onUnmounted(clearVoucherPreview);
watch(()=>[props.kind,props.id],()=>{domesticPaymentsOpen.value=false;voucherPreviewOpen.value=false;clearVoucherPreview();});
async function downloadVoucher(row,voucher){const result=await voucherApi.downloadSettlementVoucher(props.kind,props.id,row.id,voucher.id,voucher.file_name);if(!result?.success)ElMessage.error(result?.message||'凭证下载失败。');}
async function loadVersion(sequence){error.value='';try{selectedVersion.value=unwrap(await api.fetchCostVersion(props.kind,props.id,sequence));}catch(e){error.value=e.message||'历史成本版本读取失败';}}
watch(()=>[props.kind,props.id],load);watch(()=>props.version,version=>{if(!context.value||String(version)===String(context.value.target?.version))return;if(dirty.value){refreshPending.value=true;return;}load();});onMounted(load);
defineExpose({load,loadVersion,addFeeItem,removeFeeItem,breakdown,feeItems,saveFee,calculate,recordSettlement,uploadVoucher,downloadVoucher,previewVoucher,context,fee,measurements,settlement,selectedVersion,refreshPending,dirty,fieldErrors});
</script>
